<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../config/db.php';
requireModuleAccess('general_ledger');
$ready=(bool)$conn->query("SHOW TABLES LIKE 'journal_lines'")->fetchColumn()&&(bool)$conn->query("SHOW TABLES LIKE 'journal_entries'")->fetchColumn();
$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$valid='/^\d{4}-\d{2}-\d{2}$/';
$from=preg_match($valid,$from)?$from:date('Y-m-01');$to=preg_match($valid,$to)?$to:date('Y-m-d');if($from>$to){[$from,$to]=[$to,$from];}
$accountId=(int)($_GET['account_id']??0);$accounts=$ready?$conn->query("SELECT id,account_code,account_name,account_type FROM accounts ORDER BY account_code")->fetchAll(PDO::FETCH_ASSOC):[];
$selected=null;foreach($accounts as $a)if((int)$a['id']===$accountId)$selected=$a;
$opening=0.0;$rows=[];$debitTotal=0.0;$creditTotal=0.0;$closing=0.0;
if($ready&&$selected){
 $normalDebit=in_array($selected['account_type'],['Asset','Expense'],true);
 $q=$conn->prepare("SELECT COALESCE(SUM(l.debit-l.credit),0) FROM journal_lines l JOIN journal_entries j ON j.id=l.journal_entry_id WHERE l.account_id=? AND j.status='Posted' AND j.journal_date<?");$q->execute([$accountId,$from]);$raw=(float)$q->fetchColumn();$opening=$normalDebit?$raw:-$raw;
 $q=$conn->prepare("SELECT j.journal_date,j.journal_number,j.description,j.reference,l.line_description,l.debit,l.credit FROM journal_lines l JOIN journal_entries j ON j.id=l.journal_entry_id WHERE l.account_id=? AND j.status='Posted' AND j.journal_date BETWEEN ? AND ? ORDER BY j.journal_date,j.id,l.id");$q->execute([$accountId,$from,$to]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);
 $running=$opening;foreach($rows as &$row){$debitTotal+=(float)$row['debit'];$creditTotal+=(float)$row['credit'];$delta=(float)$row['debit']-(float)$row['credit'];$running+=$normalDebit?$delta:-$delta;$row['running']=$running;}unset($row);$closing=$running;
}
$currency=(string)($conn->query("SELECT setting_value FROM settings WHERE setting_key='currency' LIMIT 1")->fetchColumn()?:'KES');
require_once __DIR__.'/../../includes/header.php';require_once __DIR__.'/../../includes/sidebar.php';
?>
<main class="content"><style>
.gl-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.gl-tabs a{padding:9px 12px;background:#edf2f7;border-radius:8px;text-decoration:none;color:#17324d;font-size:12px;font-weight:800}.gl-panel{background:#fff;border:1px solid #e5eaf0;border-radius:12px;padding:16px;margin:14px 0}.gl-filter{display:flex;gap:10px;flex-wrap:wrap;align-items:end}.gl-filter label{font-size:11px;font-weight:800;display:flex;flex-direction:column;gap:5px}.gl-filter input,.gl-filter select{padding:9px;border:1px solid #cbd5e1;border-radius:7px}.gl-btn{background:#174a7e;color:white;border:0;border-radius:7px;padding:10px 14px;font-weight:800}.gl-table{width:100%;border-collapse:collapse}.gl-table th,.gl-table td{padding:9px;border-bottom:1px solid #edf1f5;text-align:left;font-size:12px}.gl-table th{background:#f3f6fa}.num{text-align:right!important;white-space:nowrap}.muted{color:#64748b}
</style>
<h1>General Ledger</h1><p class="muted">Posted journal activity by account, including brought-forward and running balances.</p><nav class="gl-tabs"><a href="chart_of_accounts.php">Chart of Accounts</a><a href="journals.php">Journal Entries</a><a href="general_ledger.php">General Ledger</a><a href="trial_balance.php">Trial Balance</a></nav>
<?php if(!$ready):?><section class="gl-panel">Import the double-entry accounting migration first.</section><?php else:?>
<section class="gl-panel"><form class="gl-filter"><label>Account<select name="account_id" required><option value="">Select account</option><?php foreach($accounts as $a):?><option value="<?=(int)$a['id']?>" <?=$accountId===(int)$a['id']?'selected':''?>><?=e($a['account_code'].' — '.$a['account_name'])?></option><?php endforeach;?></select></label><label>From<input type="date" name="from" value="<?=e($from)?>"></label><label>To<input type="date" name="to" value="<?=e($to)?>"></label><button class="gl-btn">View ledger</button></form></section>
<?php if($selected):?><section class="gl-panel"><h2><?=e($selected['account_code'].' — '.$selected['account_name'])?></h2><p>Opening balance: <strong><?=e($currency)?> <?=number_format(abs($opening),2)?> <?=$opening>=0?($normalDebit?'Dr':'Cr'):($normalDebit?'Cr':'Dr')?></strong> &nbsp; Period debits: <strong><?=number_format($debitTotal,2)?></strong> &nbsp; Period credits: <strong><?=number_format($creditTotal,2)?></strong> &nbsp; Closing balance: <strong><?=e($currency)?> <?=number_format(abs($closing),2)?> <?=$closing>=0?($normalDebit?'Dr':'Cr'):($normalDebit?'Cr':'Dr')?></strong></p><div style="overflow:auto"><table class="gl-table"><thead><tr><th>Date</th><th>Journal</th><th>Description</th><th>Reference</th><th class="num">Debit</th><th class="num">Credit</th><th class="num">Running balance</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><td><?=e($row['journal_date'])?></td><td><?=e($row['journal_number'])?></td><td><?=e($row['line_description']?:$row['description'])?></td><td><?=e($row['reference']??'—')?></td><td class="num"><?=number_format((float)$row['debit'],2)?></td><td class="num"><?=number_format((float)$row['credit'],2)?></td><td class="num"><?=number_format(abs((float)$row['running']),2)?> <?=((float)$row['running'])>=0?($normalDebit?'Dr':'Cr'):($normalDebit?'Cr':'Dr')?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="muted">No posted activity for this account in the selected period.</td></tr><?php endif;?></tbody></table></div></section><?php else:?><section class="gl-panel muted">Choose an account to view its General Ledger.</section><?php endif;?><?php endif;?></main><?php require_once __DIR__.'/../../includes/footer.php';?>
